def kthSmallestStream(ops):
    vals = sorted({x for t, x in ops if t == 1})
    pos = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)
    top = 1
    while top * 2 <= m:
        top *= 2
    out = []
    for t, x in ops:
        if t == 3:
            k = x
            cur = 0
            step = top
            while step:
                nxt = cur + step
                if nxt <= m and tree[nxt] < k:
                    cur = nxt
                    k -= tree[nxt]
                step //= 2
            out.append(vals[cur])
        else:
            d = 1 if t == 1 else -1
            i = pos[x]
            while i <= m:
                tree[i] += d
                i += i & -i
    return out
